VIEWS.dashboard=function(){const st=students();const inv=syInv();const fact=sum(inv.map(invTtcLocal)),paid=sum(inv.map(invPaid));const attendu=sum(st.map(annualFee));const late=lateStudents();const lateAmt=sum(late.map(s=>stuBal(s).late));
 const cash=totalCash();const months=exMonths();const R=roles();const res=result();
 const encM=months.map(m=>sum(S.txs.filter(t=>t.date.startsWith(m)&&t.match&&t.match.t==='inv').map(t=>t.amount)));
 const depM=months.map(m=>sum(S.txs.filter(t=>t.date.startsWith(m)&&t.amount<0&&t.acc!==R.transfer).map(t=>-t.amount)));
 const cyc={};for(const s of st){const c=cyc[s.cycle]=cyc[s.cycle]||{n:0,due:0,paid:0};c.n++;for(const i of stuInv(s.id).filter(i=>i.sy===S.schoolYear)){c.due+=invTtcLocal(i);c.paid+=invPaid(i)}}
 const modes={};for(const t of S.txs)if(t.match&&t.match.t==='inv'&&invById(t.match.id).sy===S.schoolYear)modes[t.tid]=(modes[t.tid]||0)+t.amount;
 const byClass={};for(const s of late){byClass[s.classe]=(byClass[s.classe]||0)+stuBal(s).late}const topCl=Object.entries(byClass).sort((a,b)=>b[1]-a[1]).slice(0,5);
 const run=S.runs[curMonth()];const rr=runResults(curMonth());
 const recent=S.txs.filter(t=>t.match&&t.match.t==='inv').slice(-5).reverse();
 const d=new Date();const greet=d.getHours()<18?'Bonjour':'Bonsoir';
 return head('Tableau de bord',`${ucf(d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}))} · ${late.length} familles à relancer`,`<button class="btn" onclick="openEncaisser()">${ic('wallet',16)} Encaisser</button><button class="btn btn-primary" onclick="openStudentForm()">${ic('plus',16)} Inscrire un élève</button>`)+
 `<div class="grid kpis">${kpi('Élèves inscrits',String(st.length),`${st.filter(s=>s.nouveau).length} nouveaux cette année`,'users','t-sky')}${kpi('Encaissé '+S.schoolYear,mshort(paid),`${pct(attendu?paid/attendu:0,0)} de l’année (${mshort(attendu)})`,'checkCircle','t-emerald',money(paid))}${kpi('Impayés échus',`<span class="${lateAmt?'neg':''}">${mshort(lateAmt)}</span>`,`${late.length} famille${late.length>1?'s':''} à relancer`,'alert','t-rose',money(lateAmt))}${kpi('Trésorerie',mshort(cash),'Banque, caisse et '+country().mm[0],'wallet','t-amber',money(cash))}</div>
 <div class="grid cols-2 mt"><div class="card"><div class="card-head"><div><h3>Encaissements et dépenses</h3><div class="xs muted">Exercice ${YEAR}, par mois</div></div><button class="btn btn-sm" onclick="go('tresorerie')">Trésorerie ${ic('chevronRight',14)}</button></div><div class="card-body">${legend([['Frais encaissés','#1f52e5'],['Dépenses','#f59e0b']])}${lineChart({labels:months.map(m=>MO[+m.slice(5)-1]),series:[{name:'Frais encaissés',color:'#1f52e5',values:encM},{name:'Dépenses',color:'#f59e0b',values:depM,dash:true}],fmt:money})}</div></div>
 <div class="card"><div class="card-head"><h3>Recouvrement ${S.schoolYear}</h3><button class="link sm" onclick="go('recouvrement')">${pct(fact?paid/fact:0,0)} encaissé</button></div><div class="card-body">${hbars(Object.entries(cyc).map(([k,c])=>({label:k+' · '+c.n+' élèves',value:c.due?c.paid/c.due:0,text:pct(c.due?c.paid/c.due:0,0),color:CYC_C[k],sub:money(c.paid)+' sur '+money(c.due)})),{max:1})}<div class="hr"></div><div class="xs muted mb" style="margin-bottom:8px">Encaissements par mode de paiement</div>${S.treasury.map(t=>`<div class="flex-between sm" style="padding:4px 0"><span class="flex">${ic(t.type==='bank'?'bank':t.type==='cash'?'cash':'phone',14)} ${MODE_LBL(t.id)}</span><span class="fw5">${money(modes[t.id]||0)}</span></div>`).join('')}</div></div></div>
 <div class="grid cols-3 mt">
 <div class="card"><div class="card-head"><h3>Classes à relancer</h3><button class="link sm" onclick="go('recouvrement')">Tout voir</button></div>${topCl.map(([c,v])=>`<div class="list-item click" onclick="ui.f.recouvrement={c:'${esc(c)}'};go('recouvrement')"><span class="ic-box t-rose">${ic('users',15)}</span><div class="grow"><div class="fw5">${esc(c)}</div><div class="xs muted">${late.filter(s=>s.classe===c).length} élève(s) en retard</div></div><div class="num fw5 neg">${money(v)}</div></div>`).join('')||'<div class="empty">Aucun impayé échu</div>'}</div>
 <div class="card"><div class="card-head"><h3>Derniers paiements</h3><button class="link sm" onclick="go('scolarite',{},'enc')">Tout voir</button></div>${recent.map(t=>{const i=invById(t.match.id);const s=client(i.clientId);return `<div class="list-item click" onclick="openReceipt('${t.id}')">${avatar(s.name,32)}<div class="grow min0"><div class="fw5 ellipsis">${esc(s.name)}</div><div class="xs muted">${esc(s.classe)} · ${MODE_LBL(t.tid)} · ${fds(t.date)}</div></div><div class="num fw5 pos">+${money(t.amount)}</div></div>`}).join('')}</div>
 <div class="card"><div class="card-head"><h3>Paie de ${MOL[+curMonth().slice(5)-1]}</h3>${run?badge(run.status==='validated'?'Validée':'En préparation',run.status==='validated'?'b-green':'b-amber'):''}</div><div class="card-body"><dl class="dl"><div><dt>Personnel payé</dt><dd>${rr.length} personnes</dd></div><div><dt>Net à verser</dt><dd>${money(sum(rr.map(r=>r.net)))}</dd></div><div><dt>Coût total</dt><dd>${money(sum(rr.map(r=>r.cost)))}</dd></div><div><dt>Résultat de l’exercice</dt><dd class="${res.res<0?'neg':'pos'}">${money(res.res)}</dd></div></dl><button class="btn w100 mt" onclick="ui.payMonth='${curMonth()}';go('paie')">Préparer la paie ${ic('chevronRight',14)}</button></div></div></div>`};
const invById=id=>cached('ib',()=>Object.fromEntries(S.invoices.map(i=>[i.id,i])))[id]||{};

