VIEWS.eleves=function(){const f=F();const all=students();let list=all.slice();
 if(f.q){const q=slug(f.q);list=list.filter(s=>slug(s.name+s.parent.name+s.matricule+s.parent.phone).includes(q))}if(f.c)list=list.filter(s=>s.classe===f.c);if(f.st==='late')list=list.filter(s=>stuBal(s).late>0.5);if(f.st==='ok')list=list.filter(s=>stuBal(s).late<=0.5);
 list.sort((a,b)=>S.fees.findIndex(x=>x.id===a.level)-S.fees.findIndex(x=>x.id===b.level)||a.nom.localeCompare(b.nom));const lim=50*((ui.limit.eleves||0)+1);
 return head('Élèves & familles',`${all.length} élèves · année scolaire ${S.schoolYear}`,`<button class="btn" onclick="exportStudents()">${ic('copy',16)} Exporter</button><button class="btn btn-primary" onclick="openStudentForm()">${ic('plus',16)} Inscrire un élève</button>`)+
 `<div class="grid kpis mb">${kpi('Filles / garçons',`${all.filter(s=>s.sexe==='F').length} / ${all.filter(s=>s.sexe==='M').length}`,S.fees.length+' classes','users','t-sky')}${kpi('Nouveaux élèves',String(all.filter(s=>s.nouveau).length),'Inscriptions '+S.schoolYear,'plus','t-violet')}${kpi('Bibliothèque numérique',String(all.filter(s=>s.cantine).length),pct(all.filter(s=>s.cantine).length/all.length,0)+' des élèves','briefcase','t-amber')}${kpi('Transport scolaire',String(all.filter(s=>s.transport).length),pct(all.filter(s=>s.transport).length/all.length,0)+' des élèves','zap','t-emerald')}</div>
 <div class="card"><div class="toolbar"><div class="input-ic grow">${ic('search',16)}<input id="q-el" class="input" placeholder="Nom de l’élève, du parent, matricule ou téléphone" value="${esc(f.q||'')}" oninput="setF('q',this.value,'q-el')"></div><select class="input w-auto" onchange="setF('c',this.value)"><option value="">Toutes les classes</option>${options(S.fees.map(l=>[l.name,l.name]),f.c)}</select><div class="seg">${[['','Tous'],['late','En retard'],['ok','À jour']].map(([k,l])=>`<button class="${(f.st||'')===k?'active':''}" onclick="setF('st','${k}')">${l}</button>`).join('')}</div></div>
 <div class="table-wrap"><table><thead><tr><th>Élève</th><th>Classe</th><th class="hide-md">Parent / tuteur</th><th class="hide-sm">Services</th><th class="num">Reste à payer</th><th>Situation</th></tr></thead><tbody>${list.slice(0,lim).map(s=>{const b=stuBal(s);return `<tr class="click" onclick="openStudent('${s.id}')"><td><div class="person">${avatar(s.name,32)}<div class="min0"><div class="n">${esc(s.name)}</div><div class="s">${s.matricule}${s.nouveau?' · nouveau':''}</div></div></div></td><td>${esc(s.classe)}</td><td class="hide-md"><div class="sm">${esc(s.parent.name)}</div><div class="xs muted">${esc(s.parent.phone)}</div></td><td class="hide-sm">${s.cantine?badge('Bibliothèque','b-amber',false):''} ${s.transport?badge('Transport','b-teal',false):''}</td><td class="num fw5">${money(b.rest)}</td><td>${b.late>0.5?badge('Retard '+money(b.late),'b-red'):b.rest>0.5?badge('À jour','b-blue'):badge('Soldé','b-green')}</td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Aucun élève</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>${list.length} élève(s)</span>${list.length>lim?`<button class="btn btn-sm" onclick="more()">Afficher plus</button>`:''}</div></div>`};
function exportStudents(){const rows=['Matricule;Nom;Classe;Parent;Téléphone;Dû;Payé;Reste'];for(const s of students()){const b=stuBal(s);rows.push([s.matricule,s.name,s.classe,s.parent.name,s.parent.phone,b.due,b.paid,b.rest].join(';'))}copyText(rows.join('\n'),'Liste des élèves copiée — collez-la dans Excel')}
function openStudent(id,tab){const s=client(id);tab=tab||'compte';const b=stuBal(s);const inv=stuInv(id).slice().sort((a,b)=>b.date.localeCompare(a.date));const pays=S.txs.filter(t=>t.match&&t.match.t==='inv'&&invById(t.match.id).clientId===id).sort((a,b)=>b.date.localeCompare(a.date));
 const tb=`<div class="tabs" style="margin-bottom:16px">${[['compte','Compte famille'],['infos','Informations']].map(([k,l])=>`<div class="tab ${k===tab?'active':''}" onclick="openStudent('${id}','${k}')">${l}</div>`).join('')}</div>`;
 let body=`<div class="flex mb" style="gap:14px">${avatar(s.name,54)}<div class="grow"><div class="fw6" style="font-size:18px">${esc(s.name)}</div><div class="muted sm">${esc(s.classe)} · ${s.matricule}${s.nouveau?' · nouvel élève':''}</div></div><div style="text-align:right"><div class="xs muted">Reste à payer</div><div class="fw6" style="font-size:20px">${money(b.rest)}</div>${b.late>0.5?`<div class="xs neg">dont ${money(b.late)} échu</div>`:''}</div></div>`+tb;
 if(tab==='compte')body+=`<div class="sec-title" style="margin-top:0">Échéances</div><div class="table-wrap" style="border:1px solid var(--border);border-radius:12px"><table><thead><tr><th>Échéance</th><th class="hide-sm">Date limite</th><th class="num">Montant</th><th class="num">Payé</th><th>Statut</th></tr></thead><tbody>${inv.map(i=>`<tr class="click" onclick="openInvoice('${i.id}')"><td class="fw5">${esc(i.label||i.num)}</td><td class="hide-sm">${fds(i.due)}</td><td class="num">${money(invTtcLocal(i))}</td><td class="num">${money(invPaid(i))}</td><td>${badge(...INV_ST[invStatus(i)])}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Aucune échéance</div></td></tr>'}</tbody></table></div><div class="sec-title">Paiements</div>${pays.length?`<div class="table-wrap" style="border:1px solid var(--border);border-radius:12px"><table><tbody>${pays.map(t=>`<tr class="click" onclick="openReceipt('${t.id}')"><td class="fw5">${t.ref}</td><td>${fds(t.date)}</td><td class="hide-sm">${MODE_LBL(t.tid)}</td><td class="num pos fw5">${money(t.amount)}</td><td class="num"><span class="link sm">Reçu</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="muted sm">Aucun paiement enregistré.</div>'}`;
 else body+=`<div class="grid cols-2e"><dl class="dl"><div><dt>Classe</dt><dd>${esc(s.classe)} (${s.cycle})</dd></div><div><dt>Sexe</dt><dd>${s.sexe==='F'?'Fille':s.sexe==='M'?'Garçon':'—'}</dd></div><div><dt>Bibliothèque numérique</dt><dd>${s.cantine?'Oui':'Non'}</dd></div><div><dt>Transport scolaire</dt><dd>${s.transport?'Oui':'Non'}</dd></div><div><dt>Frais annuels</dt><dd>${money(annualFee(s))}</dd></div></dl><dl class="dl"><div><dt>Parent / tuteur</dt><dd>${esc(s.parent.name)}</dd></div><div><dt>Téléphone</dt><dd>${esc(s.parent.phone)}</dd></div><div><dt>Mobile Money</dt><dd>${esc(s.parent.mm||'—')}</dd></div><div><dt>Dernière relance</dt><dd>${S.relances[id]?fds(S.relances[id]):'—'}</dd></div></dl></div>`;
 const open=inv.filter(i=>invStatus(i)!=='paid').sort((a,b)=>a.due.localeCompare(b.due))[0];
 modal('Dossier élève',body,`<div class="left"><button class="btn" onclick="openStudentForm('${id}')">${ic('edit',16)} Modifier</button></div>${b.late>0.5?`<button class="btn" onclick="openRelance('${id}')">${ic('send',16)} Relancer</button>`:''}${open?`<button class="btn btn-primary" onclick="openEncaisser('${open.id}')">${ic('wallet',16)} Encaisser</button>`:''}`,'wide')}
function openStudentForm(id){const s=id?client(id):{prenom:'',nom:'',sexe:'F',level:S.fees[0].id,nouveau:true,cantine:false,transport:false,parent:{civ:'Mme',name:'',phone:'',mm:country().mm[0]}};
 modal(id?'Modifier l’élève':'Inscrire un élève',`<div class="form-grid"><div class="form-section">Élève</div>${field('Prénom','sf-p',s.prenom)}${field('Nom','sf-n',s.nom)}${selectF('Sexe','sf-sx',[['F','Fille'],['M','Garçon']],s.sexe)}${selectF('Classe','sf-l',S.fees.map(l=>[l.id,l.name+' · '+money(l.scol)+' / an']),s.level)}<label class="check field full"><input type="checkbox" id="sf-cn" ${s.cantine?'checked':''}> Bibliothèque numérique (${money(S.feeOpts.cantine)} / an)</label><label class="check field full"><input type="checkbox" id="sf-tr" ${s.transport?'checked':''}> Transport scolaire (${money(S.feeOpts.transport)} / an)</label>${id?'':`<label class="check field full"><input type="checkbox" id="sf-nv" checked> Nouvel élève (frais d’inscription et tenue facturés)</label>`}<div class="form-section">Parent / tuteur</div>${field('Nom complet','sf-pn',s.parent.name,{attrs:'placeholder="Ex. Mme Chantal Mukendi"'})}${field('Téléphone','sf-pt',s.parent.phone)}${selectF('Mobile Money','sf-mm',country().mm.map(x=>[x,x]),s.parent.mm)}</div>${id?'':`<div class="note mt">${ic('info',16)}<div>L’échéance de la tranche en cours (${S.schoolYear}) sera créée automatiquement selon la grille tarifaire.</div></div>`}`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn btn-primary" onclick="saveStudent('${id||''}')">${id?'Enregistrer':'Inscrire l’élève'}</button>`)}
function saveStudent(id){const p=val('sf-p'),n=val('sf-n');if(!p||!n){toast('Prénom et nom obligatoires','err');return}const lv=S.fees.find(l=>l.id===val('sf-l'));
 const base=id?client(id):{id:uid('el'),type:'eleve',matricule:(S.country==='CD'?'LAIS-':'GSE-')+String(26000+S.clients.length+1),nouveau:document.getElementById('sf-nv').checked,country:S.company.country,city:S.company.city,currency:S.currency,terms:15,email:'',birth:''};
 Object.assign(base,{prenom:p,nom:n,name:p+' '+n.toUpperCase(),sexe:val('sf-sx'),level:lv.id,classe:lv.name,cycle:lv.cycle,cantine:document.getElementById('sf-cn').checked,transport:document.getElementById('sf-tr').checked,parent:{civ:'',name:val('sf-pn')||'—',phone:val('sf-pt'),mm:val('sf-mm')}});
 if(!id){S.clients.push(base);S.seq.inv++;const inv={id:uid('iv'),num:'F-'+TODAY.slice(0,4)+'-'+String(S.seq.inv).padStart(5,'0'),clientId:base.id,date:TODAY,due:addDays(TODAY,15),currency:S.currency,rate:1,lines:feeLines(base,{n:1,sy:S.schoolYear,pct:S.tranches[0]}),status:'sent',notes:'',label:'1re tranche '+S.schoolYear,sy:S.schoolYear,tranche:1};S.invoices.push(inv)}
 save();render();openStudent(base.id);toast(id?'Dossier mis à jour':'Élève inscrit — échéance de rentrée créée')}

/* ================= FRAIS DE SCOLARITÉ ================= */
VIEWS.scolarite=function(){const tab=tabOf('ech');const f=F();const inv=syInv();const fact=sum(inv.map(invTtcLocal)),paid=sum(inv.map(invPaid));const late=sum(inv.filter(i=>invStatus(i)==='late').map(i=>invTtcLocal(i)-invPaid(i)));
 let h=head('Frais de scolarité',`Échéances, encaissements et reçus · ${S.schoolYear}`,`<button class="btn" onclick="openInvEditor(null,'inv')">${ic('file',16)} Facture ponctuelle</button><button class="btn btn-primary" onclick="openEncaisser()">${ic('wallet',16)} Encaisser un paiement</button>`)+
 `<div class="grid kpis mb">${kpi('Facturé '+S.schoolYear,mshort(fact),inv.length+' échéances émises','receipt','t-sky',money(fact))}${kpi('Encaissé',mshort(paid),pct(fact?paid/fact:0,0)+' recouvré','checkCircle','t-emerald',money(paid))}${kpi('Reste à encaisser',mshort(fact-paid),'Tranche en cours','clock','t-amber',money(fact-paid))}${kpi('Échu impayé',`<span class="${late?'neg':''}">${mshort(late)}</span>`,'Toutes années confondues : '+money(sum(lateStudents().map(s=>stuBal(s).late))),'alert','t-rose',money(late))}</div>`+tabs([['ech','Échéances'],['enc','Encaissements & reçus']],tab);
 if(tab==='enc'){let list=S.txs.filter(t=>t.match&&t.match.t==='inv');if(f.q){const q=slug(f.q);list=list.filter(t=>slug(t.label+t.ref).includes(q))}if(f.mode)list=list.filter(t=>t.tid===f.mode);list=list.slice().reverse();const lim=50*((ui.limit.scolarite||0)+1);
  return h+`<div class="card"><div class="toolbar"><div class="input-ic grow">${ic('search',16)}<input id="q-enc" class="input" placeholder="Élève ou n° de reçu" value="${esc(f.q||'')}" oninput="setF('q',this.value,'q-enc')"></div><div class="seg">${[['','Tous'],['c1','Espèces'],['m1',country().mm[0]],['b1','Banque']].map(([k,l])=>`<button class="${(f.mode||'')===k?'active':''}" onclick="setF('mode','${k}')">${l}</button>`).join('')}</div></div><div class="table-wrap"><table><thead><tr><th>Reçu</th><th>Date</th><th>Élève</th><th class="hide-sm">Mode</th><th class="num">Montant</th><th></th></tr></thead><tbody>${list.slice(0,lim).map(t=>{const i=invById(t.match.id),s=client(i.clientId);return `<tr class="click" onclick="openReceipt('${t.id}')"><td class="fw5">${t.ref}</td><td>${fds(t.date)}</td><td><div class="person">${avatar(s.name,28)}<div class="min0"><div class="n">${esc(s.name)}</div><div class="s">${esc(s.classe)} · ${esc(i.label||'')}</div></div></div></td><td class="hide-sm">${MODE_LBL(t.tid)}</td><td class="num fw5 pos">${money(t.amount)}</td><td class="num"><span class="link sm">Reçu</span></td></tr>`}).join('')}</tbody></table></div><div class="table-foot"><span>${list.length} paiement(s) · ${money(sum(list.map(t=>t.amount)))}</span>${list.length>lim?`<button class="btn btn-sm" onclick="more()">Afficher plus</button>`:''}</div></div>`}
 const trs=[...new Set(S.invoices.map(i=>i.label))].filter(Boolean);let list=S.invoices.filter(i=>i.status!=='cancelled');if(!f.tr&&f.tr!=='all')f.tr=trs[trs.length-1]||'all';
 if(f.tr&&f.tr!=='all')list=list.filter(i=>i.label===f.tr);if(f.c)list=list.filter(i=>client(i.clientId).classe===f.c);if(f.q){const q=slug(f.q);list=list.filter(i=>slug(client(i.clientId).name+i.num).includes(q))}if(f.st)list=list.filter(i=>{const s=invStatus(i);return f.st==='open'?s!=='paid':s===f.st});
 list.sort((a,b)=>b.date.localeCompare(a.date)||client(a.clientId).name.localeCompare(client(b.clientId).name));const lim=50*((ui.limit.scolarite||0)+1);
 return h+`<div class="card"><div class="toolbar"><div class="input-ic grow">${ic('search',16)}<input id="q-ech" class="input" placeholder="Élève ou n° de facture" value="${esc(f.q||'')}" oninput="setF('q',this.value,'q-ech')"></div><select class="input w-auto" onchange="setF('tr',this.value)"><option value="all">Toutes les échéances</option>${options(trs.map(t=>[t,ucf(t)]),f.tr)}</select><select class="input w-auto hide-sm" onchange="setF('c',this.value)"><option value="">Toutes les classes</option>${options(S.fees.map(l=>[l.name,l.name]),f.c)}</select><select class="input w-auto hide-sm" onchange="setF('st',this.value)"><option value="">Tous les statuts</option>${options([['open','Non soldées'],['late','En retard'],['partial','Partielles'],['paid','Payées']],f.st)}</select></div>
 <div class="table-wrap"><table><thead><tr><th>Élève</th><th class="hide-sm">Échéance</th><th class="num">Montant</th><th class="num hide-sm">Payé</th><th class="num">Reste</th><th>Statut</th><th></th></tr></thead><tbody>${list.slice(0,lim).map(i=>{const s=client(i.clientId),st=invStatus(i),t=invTtcLocal(i),p=invPaid(i);return `<tr class="click" onclick="openInvoice('${i.id}')"><td><div class="person">${avatar(s.name,30)}<div class="min0"><div class="n">${esc(s.name)}</div><div class="s">${esc(s.classe||'')} · ${i.num||'brouillon'}</div></div></div></td><td class="hide-sm"><div class="sm">${esc(ucf(i.label||'Facture'))}</div><div class="xs ${st==='late'?'neg':'muted'}">avant le ${fds(i.due)}</div></td><td class="num">${money(t)}</td><td class="num hide-sm">${money(p)}</td><td class="num fw5">${money(Math.max(0,t-p))}</td><td>${badge(...INV_ST[st])}</td><td class="num">${st!=='paid'&&st!=='draft'?`<button class="btn btn-xs btn-primary" onclick="event.stopPropagation();openEncaisser('${i.id}')">Encaisser</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="7"><div class="empty">Aucune échéance</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>${list.length} échéance(s) · reste ${money(sum(list.map(i=>Math.max(0,invTtcLocal(i)-invPaid(i)))))}</span>${list.length>lim?`<button class="btn btn-sm" onclick="more()">Afficher plus</button>`:''}</div></div>`};
function openEncaisser(invId,stuId){const sts=students().slice().sort((a,b)=>S.fees.findIndex(x=>x.id===a.level)-S.fees.findIndex(x=>x.id===b.level)||a.name.localeCompare(b.name));
 const i=invId?S.invoices.find(x=>x.id===invId):null;const sid=i?i.clientId:(stuId||sts[0].id);const s=client(sid);const open=stuInv(sid).filter(x=>invStatus(x)!=='paid').sort((a,b)=>a.due.localeCompare(b.due));const cur=i||open[0];const rem=cur?rnd(invTtcLocal(cur)-invPaid(cur)):0;
 modal('Encaisser un paiement',`<div class="form-grid">${selectF('Élève','en-s',sts.map(x=>[x.id,x.classe+' · '+x.name]),sid,{full:true,attrs:'onchange="openEncaisser(null,this.value)"'})}${open.length?selectF('Échéance','en-i',open.map(x=>[x.id,ucf(x.label||x.num)+' · reste '+money(invTtcLocal(x)-invPaid(x))]),cur.id,{full:true,attrs:'onchange="openEncaisser(this.value)"'}):'<div class="field full"><div class="note ok">'+ic('checkCircle',16)+'<div>Toutes les échéances de cet élève sont soldées.</div></div></div>'}${field('Montant reçu ('+S.currency+')','en-a',rem)}${field('Date','en-d',TODAY,{type:'date'})}${selectF('Mode de paiement','en-t',[['c1','Espèces (caisse)'],['m1',country().mm.join(' / ')],['b1','Versement / virement bancaire']],'c1')}${field('Référence de transaction','en-r','',{attrs:'placeholder="Facultatif (n° Mobile Money, bordereau…)"'})}${field('Versé par','en-p',s.parent.name,{full:true})}</div>`,`<button class="btn" onclick="closeModal()">Annuler</button>${open.length?`<button class="btn btn-primary" onclick="saveEncaisser()">${ic('check',16)} Encaisser et éditer le reçu</button>`:''}`)}
function saveEncaisser(){const iid=val('en-i');const a=parseNum(val('en-a'));if(!iid||!(a>0)){toast('Montant invalide','err');return}const i=S.invoices.find(x=>x.id===iid),s=client(i.clientId);const tid=val('en-t');const d=val('en-d')||TODAY;S.seq.rec=Math.max(S.seq.rec||0,...S.txs.map(x=>{const m=/^REC-\d{4}-(\d+)$/.exec(x.ref||'');return m?+m[1]:0}))+1;
 const t={id:uid('tx'),tid,date:d,label:`${MODE_LBL(tid)} – ${s.name} (${s.classe}) – ${i.label||i.num}`,amount:rnd(a),acc:null,match:{t:'inv',id:iid},ref:'REC-'+d.slice(0,4)+'-'+String(S.seq.rec).padStart(5,'0'),payer:val('en-p'),txref:val('en-r')};S.txs.push(t);save();render();openReceipt(t.id);toast('Paiement encaissé — reçu '+t.ref)}
function receiptHTML(t){const i=invById(t.match.id),s=client(i.clientId),co=S.company;const after=rnd(invTtcLocal(i)-sum(S.txs.filter(x=>x.match&&x.match.id===i.id&&(x.date<t.date||(x.date===t.date&&x.ref<=t.ref))).map(x=>x.amount)));const bal=stuBal(s);
 return `<div class="paper receipt"><div class="paper-head"><div class="flex" style="gap:12px"><div class="logo-sq" style="width:42px;height:42px;font-size:18px">${orgIni()}</div><div><div class="co">${esc(co.name)}</div>${co.motto?`<div class="motto">${esc(co.motto)}</div>`:''}<div class="xs muted">${esc(co.address)}, ${esc(co.city)} · ${esc(co.phone)}</div></div></div><div style="text-align:right"><div class="doc-title">REÇU</div><div class="sm fw6">${t.ref}</div><div class="xs muted">${fd(t.date)}</div></div></div>
 <div class="rc-amount"><div class="xs muted">Montant reçu</div><div class="big">${money(t.amount)}</div><div class="sm">${amountWords(t.amount)}</div></div>
 <dl class="dl"><div><dt>Reçu de</dt><dd>${esc(t.payer||s.parent.name)}</dd></div><div><dt>Pour l’élève</dt><dd>${esc(s.name)} – ${esc(s.classe)} (${s.matricule})</dd></div><div><dt>Objet</dt><dd>${esc(ucf(i.label||'Facture '+i.num))}</dd></div><div><dt>Mode de paiement</dt><dd>${MODE_LBL(t.tid)}${t.txref?' · réf. '+esc(t.txref):''}</dd></div><div><dt>Reste sur cette échéance</dt><dd>${money(Math.max(0,after))}</dd></div><div><dt>Solde total du dossier</dt><dd>${money(bal.rest)}</dd></div></dl>
 <div class="sign"><div>Le parent<br><br>&nbsp;</div><div>Pour l’économat<br><b>${esc(co.name)}</b></div></div><div class="legal">Reçu édité par le service de l’économat. Les frais de scolarité versés ne sont pas remboursables, sauf dispositions du règlement intérieur.</div></div>`}
function openReceipt(id){const t=S.txs.find(x=>x.id===id);if(!t)return;const i=invById(t.match.id);modal('Reçu '+t.ref,receiptHTML(t),`<div class="left"><button class="btn" onclick="openStudent('${i.clientId}')">Dossier élève</button></div><button class="btn" onclick="copyText(document.querySelector('.modal .paper').innerText,'Reçu copié')">${ic('copy',16)} Copier</button><button class="btn btn-primary" onclick="shareReceipt('${id}')">${ic('send',16)} Envoyer au parent</button>`,'wide')}
function waLink(phone,text){return 'https://wa.me/'+String(phone).replace(/\D/g,'')+'?text='+encodeURIComponent(text)}
function shareReceipt(id){const t=S.txs.find(x=>x.id===id),i=invById(t.match.id),s=client(i.clientId);const msg=`Bonjour ${s.parent.name}, nous accusons réception de ${money(t.amount)} pour ${s.name} (${s.classe}) – ${i.label}. Reçu n° ${t.ref} du ${fds(t.date)}. Merci. ${S.company.name}`;
 modal('Envoyer le reçu',`<textarea class="input" rows="5" id="msg">${esc(msg)}</textarea><div class="hint">Numéro du parent : ${esc(s.parent.phone)}</div>`,`<button class="btn" onclick="copyText(val('msg'),'Message copié')">${ic('copy',16)} Copier</button><a class="btn btn-primary" target="_blank" rel="noopener" href="${waLink(s.parent.phone,msg)}" style="text-decoration:none">Ouvrir WhatsApp</a>`)}

/* ================= RECOUVREMENT ================= */
VIEWS.recouvrement=function(){const f=F();const late=lateStudents();const lateAmt=sum(late.map(s=>stuBal(s).late));const inv=S.invoices.filter(i=>i.status!=='draft'&&i.status!=='cancelled'&&i.due<TODAY);const dueAmt=sum(inv.map(invTtcLocal)),paidDue=sum(inv.map(invPaid));const old=sum(S.invoices.filter(i=>i.sy==='2025-2026').map(i=>Math.max(0,invTtcLocal(i)-invPaid(i))));
 const rows=S.fees.map(l=>{const ss=students().filter(s=>s.level===l.id);let d=0,p=0,lt=0;for(const s of ss){for(const i of stuInv(s.id).filter(i=>i.sy===S.schoolYear)){d+=invTtcLocal(i);p+=invPaid(i)}lt+=stuBal(s).late}return{l,n:ss.length,d,p,lt,nl:ss.filter(s=>stuBal(s).late>0.5).length}});
 let list=late.slice();if(f.c)list=list.filter(s=>s.classe===f.c);if(f.q){const q=slug(f.q);list=list.filter(s=>slug(s.name+s.parent.name).includes(q))}list.sort((a,b)=>stuBal(b).late-stuBal(a).late);
 return head('Recouvrement',`${late.length} familles en retard · ${money(lateAmt)} échus`,`<button class="btn" onclick="openRelanceAll()">${ic('send',16)} Relance groupée</button>`)+
 `<div class="grid kpis mb">${kpi('Impayés échus',`<span class="neg">${mshort(lateAmt)}</span>`,late.length+' familles concernées','alert','t-rose',money(lateAmt))}${kpi('Taux de recouvrement',pct(dueAmt?paidDue/dueAmt:1,1),'Sur les échéances passées','checkCircle','t-emerald')}${kpi('Reliquat '+'2025-2026',mshort(old),'Créances de l’année précédente','clock','t-amber',money(old))}${kpi('Relancées',String(Object.keys(S.relances).filter(k=>late.some(s=>s.id===k)).length),'Familles relancées','send','t-sky')}</div>
 ${classCards(l=>`setF('c','${esc(l.name)}')`)}
 <div class="card"><div class="card-head"><h3>Familles en retard ${f.c?'· '+esc(f.c)+' <button class="link xs" onclick="setF(\'c\',\'\')">effacer</button>':''}</h3><div class="input-ic" style="width:260px">${ic('search',16)}<input id="q-rec" class="input sm" placeholder="Rechercher" value="${esc(f.q||'')}" oninput="setF('q',this.value,'q-rec')"></div></div><div class="table-wrap"><table><thead><tr><th>Élève</th><th class="hide-md">Parent / tuteur</th><th class="num">Échu impayé</th><th class="hide-sm">Retard</th><th class="hide-md">Relance</th><th></th></tr></thead><tbody>${list.map(s=>{const b=stuBal(s);const days=Math.round((pd(TODAY)-pd(b.oldest))/864e5);return `<tr><td><div class="person click" style="cursor:pointer" onclick="openStudent('${s.id}')">${avatar(s.name,30)}<div class="min0"><div class="n">${esc(s.name)}</div><div class="s">${esc(s.classe)}</div></div></div></td><td class="hide-md"><div class="sm">${esc(s.parent.name)}</div><div class="xs muted">${esc(s.parent.phone)}</div></td><td class="num fw6 neg">${money(b.late)}</td><td class="hide-sm">${badge(days+' j',days>60?'b-red':days>20?'b-amber':'b-gray',false)}</td><td class="hide-md sm muted">${S.relances[s.id]?fds(S.relances[s.id]):'Jamais'}</td><td class="num"><div class="flex" style="justify-content:flex-end"><button class="btn btn-xs" onclick="openRelance('${s.id}')">${ic('send',12)} Relancer</button><button class="btn btn-xs btn-primary" onclick="openEncaisser(null,'${s.id}')">Encaisser</button></div></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Aucune famille en retard</div></td></tr>'}</tbody></table></div></div>`};
function relanceText(s){const b=stuBal(s);return `Bonjour ${s.parent.name}, sauf erreur de notre part, il reste ${money(b.late)} à régler pour la scolarité de ${s.name} (${s.classe}), échu depuis le ${fds(b.oldest)}. Vous pouvez payer à la caisse de l’école, par ${country().mm[0]} au ${S.company.phone} ou par virement. Merci de votre confiance. – L’économat, ${S.company.name}`}
function openRelance(id){const s=client(id);const msg=relanceText(s);modal('Relancer la famille',`<div class="flex mb">${avatar(s.name,40)}<div><div class="fw6">${esc(s.parent.name)}</div><div class="sm muted">${esc(s.parent.phone)} · parent de ${esc(s.name)}</div></div></div><textarea class="input" rows="6" id="msg">${esc(msg)}</textarea>`,`<button class="btn" onclick="copyText(val('msg'),'Message copié');markRelance('${id}')">${ic('copy',16)} Copier pour SMS</button><a class="btn btn-primary" target="_blank" rel="noopener" style="text-decoration:none" href="${waLink(s.parent.phone,msg)}" onclick="markRelance('${id}')">Envoyer par WhatsApp</a>`)}
function markRelance(id){S.relances[id]=TODAY;save();setTimeout(()=>{render()},50)}
function openRelanceAll(){const late=lateStudents();const txt=late.map(s=>`${s.parent.phone} – ${s.parent.name} (${s.name}, ${s.classe}) : ${money(stuBal(s).late)}`).join('\n');modal('Relance groupée',`<p class="sm muted" style="margin-top:0">${late.length} familles en retard. Copiez la liste pour votre envoi groupé de SMS, ou relancez chaque famille individuellement.</p><textarea class="input" rows="12" id="msg">${esc(txt)}</textarea>`,`<button class="btn btn-primary" onclick="copyText(val('msg'),'Liste copiée');late_mark()">${ic('copy',16)} Copier la liste</button>`)}
function late_mark(){for(const s of lateStudents())S.relances[s.id]=TODAY;save();closeModal();render()}

/* ================= FOURNISSEURS (seuls) ================= */
const _tiers=VIEWS.tiers;VIEWS.tiers=function(){ui.tab.tiers='fournisseurs';return _tiers().replace(/<div class="tabs">[\s\S]*?<\/div><\/div>/,'').replace('Clients & fournisseurs','Fournisseurs').replace('Annuaire des tiers, encours et historique, en Afrique comme à l’international.','Prestataires et fournisseurs de l’établissement.')};

/* ================= GRILLE TARIFAIRE ================= */
function tarifsView(){return `<div class="card mb"><div class="card-head"><h3>Grille tarifaire ${S.schoolYear}</h3><span class="xs muted">Montants annuels en ${S.currency}</span></div><div class="table-wrap"><table><thead><tr><th>Classe</th><th>Cycle</th><th class="num">Inscription</th><th class="num">Réinscription</th><th class="num">${S.country==='CD'?'Minerval':'Scolarité'} annuelle</th></tr></thead><tbody>${S.fees.map((l,i)=>`<tr><td class="fw5">${esc(l.name)}</td><td>${badge(l.cycle,'b-gray',false)}</td>${['insc','reinsc','scol'].map(k=>`<td class="num"><input class="var-in" style="width:120px" value="${l[k]}" onchange="S.fees[${i}].${k}=parseNum(this.value);save();toast('Tarif mis à jour')"></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>
 <div class="grid cols-2e"><div class="card"><div class="card-head"><h3>Services et options</h3></div><div class="table-wrap"><table><tbody>${[['cantine','Bibliothèque numérique (par an)'],['transport','Transport scolaire (par an)'],['tenue','Tenue scolaire'],['examen','Frais d’examen']].map(([k,l])=>`<tr><td>${l}</td><td class="num"><input class="var-in" style="width:120px" value="${S.feeOpts[k]}" onchange="S.feeOpts.${k}=parseNum(this.value);save();toast('Tarif mis à jour')"></td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><div class="card-head"><h3>Échéancier</h3></div><div class="card-body"><dl class="dl"><div><dt>1re tranche · ${S.country==='CD'?'du 1er septembre au 5 novembre':'rentrée (septembre)'}</dt><dd>${S.tranches[0]} %</dd></div><div><dt>2e tranche · ${S.country==='CD'?'du 5 novembre au 5 février':'janvier'}</dt><dd>${S.tranches[1]} %</dd></div><div><dt>3e tranche · ${S.country==='CD'?'du 5 février au 5 avril':'avril'}</dt><dd>${S.tranches[2]} %</dd></div></dl><div class="hint">Les frais d’inscription et la tenue sont facturés avec la 1re tranche.</div></div></div></div>`}

/* ================= HABILLAGE DOXHA ================= */
const SPARK='';const _SPARK_OLD='<svg class="spark" width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M12 0l2.6 9.4L24 12l-9.4 2.6L12 24l-2.6-9.4L0 12l9.4-2.6z"/></svg>';
function orgIni(){return S.company.name.split(/\s+/).filter(w=>w.length>2&&!/^(les|des|du|de)$/i.test(w)).map(w=>w[0]).slice(0,2).join('').toUpperCase()}
function sidebar(){const me=S.employees[2]||{prenom:'Admin',poste:'admin'};return `<aside class="sidebar ${ui.sidebarOpen?'open':''}"><div class="brand"><div class="logo-sq">L${SPARK}</div><div class="brand-name">Light Academy</div></div>
 <div class="org-card" onclick="go('parametres')"><div class="org-ini">${orgIni()}</div><div class="min0 grow"><div class="fw6 ellipsis">${esc(S.company.name)}</div><div class="sm muted">${students().length} élèves · ${S.currency}</div></div>${ic('chevronRight',16)}</div>
 <nav class="nav">${NAV.map(([sec,items])=>`${sec?`<div class="nav-section">${sec}</div>`:''}${items.map(([id,label,icon])=>{const c=navCount(id);return `<a class="${ui.page===id?'active':''}" onclick="go('${id}')">${ic(icon,18)}<span>${label}</span>${c?`<span class="count">${c}</span>`:''}</a>`}).join('')}`).join('')}</nav>
 <div class="sidebar-foot"><div class="me-row"><div class="me-av">${esc(me.prenom[0])}</div><div class="min0"><div class="fw6">${esc(me.prenom)}</div><div class="sm muted ellipsis">${esc(me.poste.split('–')[0].trim().toLowerCase())}</div></div></div><div class="foot-links"><span onclick="go('parametres',{},'pays')">${country().flag} ${esc(country().name)}</span><span onclick="go('parametres')">Paramètres</span></div></div></aside>`}
function topbar(){return `<header class="topbar"><button class="icon-btn menu-btn" onclick="toggleSidebar(true)" aria-label="Menu">${ic('menu')}</button><div class="top-search input-ic">${ic('search',18)}<input id="gs" class="input" placeholder="Rechercher un élève, une facture, un reçu…" autocomplete="off" oninput="gsearch(this.value)" onfocus="gsearch(this.value)" onblur="setTimeout(()=>{const r=document.getElementById('gs-res');r&&r.classList.remove('show')},180)"><span class="kbd">/</span><div id="gs-res" class="search-res"></div></div><div class="topbar-right"><button class="top-ic" title="Derniers encaissements" onclick="go('scolarite',{},'enc')">${ic('clock',19)}</button><button class="top-ic" title="Paramètres" onclick="go('parametres')">${ic('settings',19)}</button><div class="me">${esc((S.employees[2]||{prenom:'A'}).prenom[0])}</div></div></header>`}
function head(title,sub,actions=''){return `<div class="page-head"><div>${sub?`<div class="eyebrow">${sub}</div>`:''}<h1>${title}</h1></div><div class="actions">${actions}</div></div>`}
function gsearch(q){const box=document.getElementById('gs-res');if(!box)return;const s=slug(q);if(s.length<2){box.classList.remove('show');return}
 const st=students().filter(x=>slug(x.name+x.matricule+x.parent.name).includes(s)).slice(0,6);const iv=S.invoices.filter(i=>slug(i.num).includes(s)).slice(0,4);const rc=S.txs.filter(t=>t.ref&&slug(t.ref).includes(s)&&t.match).slice(0,4);
 box.innerHTML=(st.length?'<div class="sr-sec">Élèves</div>'+st.map(x=>`<div class="sr-item" onmousedown="openStudent('${x.id}')">${avatar(x.name,30)}<div class="min0"><div class="fw5">${esc(x.name)}</div><div class="xs muted">${esc(x.classe)} · ${esc(x.parent.name)}</div></div><span class="sm muted" style="margin-left:auto">${money(stuBal(x).rest)}</span></div>`).join(''):'')+(iv.length?'<div class="sr-sec">Factures</div>'+iv.map(i=>`<div class="sr-item" onmousedown="openInvoice('${i.id}')">${ic('receipt',16)}<div><div class="fw5">${i.num}</div><div class="xs muted">${esc(client(i.clientId).name)}</div></div></div>`).join(''):'')+(rc.length?'<div class="sr-sec">Reçus</div>'+rc.map(t=>`<div class="sr-item" onmousedown="openReceipt('${t.id}')">${ic('file',16)}<div><div class="fw5">${t.ref}</div><div class="xs muted">${money(t.amount)} · ${fds(t.date)}</div></div></div>`).join(''):'')||'<div class="sr-sec">Aucun résultat</div>';box.classList.add('show')}
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){const g=document.getElementById('gs');if(g){e.preventDefault();g.focus()}}});
function classCards(onclick){return `<div class="class-grid mb">${S.fees.map(l=>{const ss=students().filter(s=>s.level===l.id);let d=0,p=0;for(const s of ss)for(const i of stuInv(s.id).filter(i=>i.sy===S.schoolYear)){d+=invTtcLocal(i);p+=invPaid(i)}const nl=ss.filter(s=>stuBal(s).late>0.5).length;const lt=sum(ss.map(s=>stuBal(s).late));const short=l.name.replace('maternelle','M').replace('primaire','P').replace(' section','').replace('Humanités','H').replace(/^(\d)(re|e) /,'$1').replace('Petite','PS').replace('Moyenne','MS').replace('Grande','GS').replace(' EB','e EB');
 return `<div class="ccard" onclick="${onclick(l)}"><div class="ccard-top ${l.cycle}"><div class="tile"><div><b>${esc(short.split(' ')[0])}</b><br><small>${({Maternelle:'Mat.',Primaire:'Prim.',Secondaire:'Sec.',Collège:'Coll.'})[l.cycle]}</small></div></div></div><div class="ccard-body"><h4>${esc(l.name)}</h4><div class="meta">${ic('users',15)} ${ss.length} élèves · ${ss.filter(s=>s.sexe==='F').length} filles</div><div class="meta">${ic('wallet',15)} ${money(p)} encaissés</div><div class="flex-between mt8"><span class="fw6 sm">${pct(d?p/d:0,0)} recouvré</span>${nl?`<span class="pillg pillr">${nl} en retard</span>`:'<span class="pillg">À jour</span>'}</div><div class="progress mt8"><span style="width:${d?Math.min(100,p/d*100):0}%;background:${l.cycle==='Maternelle'?'#f59e0b':l.cycle==='Primaire'?'#10b981':'#1f52e5'}"></span></div>${lt?`<div class="xs neg mt8">${money(lt)} échu impayé</div>`:''}</div></div>`}).join('')}</div>`}
